// ── Estimation helper — back-of-envelope in runnable form ───────
const DAU          = 100_000_000;   // 100 M daily active users
const reqPerDay    = 50;            // requests per user per day
const avgSizeKB    = 5;             // avg request/response payload KB
const retentionYrs = 5;             // data retention years

const totalReqDay    = DAU * reqPerDay;
const avgQPS         = Math.round(totalReqDay / 86_400);
const peakQPS        = avgQPS * 3;   // 3× peak multiplier
const bandwidthGBs   = (avgQPS * avgSizeKB) / (1024 * 1024);
const storagePerDay  = (totalReqDay * avgSizeKB) / (1024 * 1024 * 1024); // GB
const storageTotalTB = storagePerDay * 365 * retentionYrs / 1024;

console.log('=== Estimation Results ===');
console.log(`Total requests/day: ${(totalReqDay / 1e9).toFixed(1)}B`);
console.log(`Average QPS:        ${avgQPS.toLocaleString()}`);
console.log(`Peak QPS (3x):      ${peakQPS.toLocaleString()}`);
console.log(`Bandwidth:          ${bandwidthGBs.toFixed(2)} GB/s`);
console.log(`Storage/day:        ${storagePerDay.toFixed(0)} GB`);
console.log(`Storage (5 years):  ${storageTotalTB.toFixed(0)} TB`);

