// ── Cursor-based pagination (API deep dive) ──────────────────────
// Offset pagination breaks on inserts: if row 50 is inserted
// between page 1 and page 2 fetches, page 2 skips row 51.
// Cursor pagination is stable:
function buildCursorQuery(lastSeenId, limit = 20) {
  // Encode the cursor as a base64 opaque token in real systems
  return {
    sql: 'SELECT * FROM posts WHERE id > ? ORDER BY id ASC LIMIT ?',
    params: [lastSeenId, limit],
    // Next cursor = last row's id from results
  };
}

// ── Cache-aside pattern (Step 5 deep dive) ───────────────────────
async function getUser(id, cache, db) {
  const key    = `user:${id}`;
  const cached = await cache.get(key);
  if (cached) return JSON.parse(cached);          // HIT: ~1ms

  const user = await db.findOne({ where: { id } }); // MISS: ~10ms
  if (user) {
    await cache.set(key, JSON.stringify(user), 'EX', 3600); // 1hr TTL
  }
  return user;
}

// ── Consistent Hash Ring (deep dive: distributed caching) ────────
function fnv1a32(str) {
  let hash = 2166136261;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = (hash * 16777619) >>> 0; // unsigned 32-bit
  }
  return hash;
}

class ConsistentHashRing {
  constructor(nodes, virtualNodes = 100) {
    this.ring = new Map();   // hash -> node
    this.sorted = [];        // sorted hashes
    for (const node of nodes) this._addNode(node, virtualNodes);
  }
  _addNode(node, replicas) {
    for (let i = 0; i < replicas; i++) {
      const h = fnv1a32(`${node}#vn${i}`);
      this.ring.set(h, node);
      this.sorted.push(h);
    }
    this.sorted.sort((a, b) => a - b);
  }
  getNode(key) {
    if (this.sorted.length === 0) return null;
    const h   = fnv1a32(key);
    let lo = 0, hi = this.sorted.length;
    while (lo < hi) {                      // binary search
      const mid = (lo + hi) >>> 1;
      if (this.sorted[mid] < h) lo = mid + 1;
      else hi = mid;
    }
    const idx = lo % this.sorted.length;   // wrap around ring
    return this.ring.get(this.sorted[idx]);
  }
}

const ring = new ConsistentHashRing(['cache-A', 'cache-B', 'cache-C']);
console.log(ring.getNode('user:1001')); // e.g. 'cache-B'
console.log(ring.getNode('session:xyz')); // deterministic assignment

// ── Token Bucket Rate Limiter (deep dive: rate limiting) ─────────
class TokenBucket {
  constructor(capacity, refillPerSec) {
    this.capacity    = capacity;
    this.tokens      = capacity;
    this.refillRate  = refillPerSec;
    this.lastRefill  = Date.now();
  }
  _refill() {
    const now     = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens   = Math.min(
      this.capacity,
      this.tokens + elapsed * this.refillRate
    );
    this.lastRefill = now;
  }
  allow(cost = 1) {
    this._refill();
    if (this.tokens >= cost) {
      this.tokens -= cost;
      return true;
    }
    return false; // rate limited
  }
}

const limiter = new TokenBucket(10, 2); // 10 capacity, 2 tokens/sec
for (let i = 1; i <= 14; i++) {
  console.log(`Request ${i}: ${limiter.allow() ? 'ALLOWED' : 'BLOCKED'}`);
}
